package com.sobrenaturaldirector.spatial.trace;
import java.util.*;
public final class SpatialPlanningTrace {public static final int MAX_EVENTS=256;private final String requestId,blueprintId;private final long seed;private final int attempts,accepted;private final List<String> events;public SpatialPlanningTrace(String requestId,String blueprintId,long seed,int attempts,int accepted,Collection<String> events){this.requestId=requestId;this.blueprintId=blueprintId;this.seed=seed;this.attempts=attempts;this.accepted=accepted;List<String>x=new ArrayList<String>(events==null?Collections.<String>emptyList():events);if(x.size()>MAX_EVENTS)throw new IllegalArgumentException("trace exceeds bound");this.events=Collections.unmodifiableList(x);}public String getRequestId(){return requestId;}public String getBlueprintId(){return blueprintId;}public long getSeed(){return seed;}public int getAttempts(){return attempts;}public int getAcceptedPlacements(){return accepted;}public List<String> getEvents(){return events;}}
